from datetime import datetime, timezone

def normalize_timestamp(value: str) -> str:
    # TODO: Implement the function as per the requirements.
    if not isinstance(value, str):
        raise ValueError("Input must be a string.")

    try:
        dt = datetime.fromisoformat(value)
    except ValueError:
        raise ValueError("Invalid ISO 8601 datetime string.")

    if dt.tzinfo is None:
        raise ValueError("Naive datetimes are not allowed, timezone information is required.")

    utc_dt = dt.astimezone(timezone.utc).replace(microsecond=0, tzinfo=None)
    return utc_dt.strftime('%Y-%m-%dT%H:%M:%SZ')

