import pytest
from app.ranges_eval import merge_ranges

def test_merge_ranges_empty():
    assert merge_ranges([]) == []

def test_merge_ranges_single_interval():
    assert merge_ranges([(1, 2)]) == [(1, 2)]

def test_merge_ranges_overlapping_intervals():
    assert merge_ranges([(1, 3), (2, 4), (5, 7)]) == [(1, 4), (5, 7)]

def test_merge_ranges_touching_intervals():
    assert merge_ranges([(1, 2), (2, 3), (4, 5)]) == [(1, 3), (4, 5)]

def test_merge_ranges_adjacent_intervals():
    assert merge_ranges([(1, 2), (3, 4), (5, 6)]) == [(1, 2), (3, 4), (5, 6)]

def test_merge_ranges_invalid_input():
    with pytest.raises(ValueError):
        merge_ranges([(1, 2), (3, 'a')])

def test_merge_ranges_bool_rejected():
    with pytest.raises(ValueError):
        merge_ranges([(True, 2)])

def test_merge_ranges_start_greater_than_end():
    with pytest.raises(ValueError):
        merge_ranges([(2, 1)])

def test_merge_ranges_no_mutation():
    intervals = [(1, 3), (2, 4), (5, 7)]
    original_intervals = intervals.copy()
    merge_ranges(intervals)
    assert intervals == original_intervals

import pytest
from app.ranges_eval import merge_ranges

def test_merge_ranges_malformed_numeric_text():
    with pytest.raises(ValueError):
        merge_ranges([(1, '2.0')])

def test_merge_ranges_nan_input():
    with pytest.raises(ValueError):
        merge_ranges([(1, float('nan'))])

def test_merge_ranges_infinity_input():
    with pytest.raises(ValueError):
        merge_ranges([(1, float('inf'))])

def test_merge_ranges_fractional_input():
    with pytest.raises(ValueError):
        merge_ranges([(1, 2.5)])

def test_merge_ranges_missing_input():
    with pytest.raises(ValueError):
        merge_ranges(None)

def test_merge_ranges_empty_input_tuple():
    with pytest.raises(ValueError):
        merge_ranges([()])

def test_merge_ranges_single_element_tuple():
    with pytest.raises(ValueError):
        merge_ranges([(1,)])

def test_merge_ranges_large_input():
    assert merge_ranges([(i, i+1) for i in range(1000)]) == [(0, 1000)]

def test_merge_ranges_exact_rounding_boundaries():
    assert merge_ranges([(1, 2), (3, 4), (5, 6)]) == [(1, 2), (3, 4), (5, 6)]

